const ancientColossusSheet=new Image();ancientColossusSheet.assetSrc='assets/ancient-colossus-v3.png';
function beginAncientColossus(e){e.state='attack';e.elapsed=0;e.struck=false;e.attack={pattern:'ancientCheckerSlam',bespoke:true,windup:1.1,origin:{x:e.x,y:e.y},center:{x:p.x,y:p.y},first:false,second:false};}
// Nine fixed 90px tiles share exact draw and contact geometry. The outer edge is excluded.
function ancientColossusTile(a,point){let x=point.x-a.center.x+135,y=point.y-a.center.y+135;if(x<0||y<0||x>=270||y>=270)return -1;return (Math.floor(x/90)+Math.floor(y/90))%2;}
const ancientColossusAnimateBase=animateEnemy;animateEnemy=(e,dt)=>{
 if(e.species!=='r9e4')return ancientColossusAnimateBase(e,dt);if(e.hp<=0||e.reactionStun>0||paused||dead||!Number.isFinite(dt)||dt<=0)return;e.anim+=dt;e.flash=Math.max(0,(e.flash||0)-dt);e.slow=Math.max(0,(e.slow||0)-dt);let a=e.attack;
 if(a?.pattern!=='ancientCheckerSlam'){e.t-=dt;e.nav=(e.nav||0)-dt;let d=dist(e,p),clear=lineClear(e,p);if(e.t<=0&&d<=280&&clear){beginAncientColossus(e);return;}e.state='idle';if(d>800&&!e.aware)return;if(e.nav<=0){e.nav=.8;e.path=clear?[{x:p.x,y:p.y}]:findPath(e,p);}let to=e.path?.[0];if(to){let dx=to.x-e.x,dy=to.y-e.y,len=Math.hypot(dx,dy);if(len<10)e.path.shift();else{let step=Math.min(len,60*(e.slow>0?.35:1)*dt);e.state=moveActor(e,dx/len*step,dy/len*step,28)>.1?'walk':'idle';e.facing=dx-dy<0?-1:1;}}return;}
 if(dist(e,a.origin)>24){e.attack=null;e.state='idle';e.t=1.5;return;}e.elapsed=Math.round((e.elapsed+dt)*1e6)/1e6;
 if(!a.first&&e.elapsed>=1.1){a.first=true;e.struck=true;if(ancientColossusTile(a,p)===0&&lineClear(a.origin,p))hurt(60);playSound('impact',e.x,e.y);}
 if(!dead&&!a.second&&e.elapsed>=2.4){a.second=true;e.struck=true;if(ancientColossusTile(a,p)===1&&lineClear(a.origin,p))hurt(86);playSound('impact',e.x,e.y);}
 if(e.elapsed>=3.3){e.attack=null;e.state='idle';e.t=3;}
};
const ancientColossusDrawBase=drawRegionEnemy;drawRegionEnemy=(e,size)=>{if(e.species!=='r9e4'||!ancientColossusSheet.complete||!ancientColossusSheet.naturalWidth||!ancientColossusSheet.naturalHeight)return ancientColossusDrawBase(e,size);let f=spriteFrame(e.state,e.anim||0);if(e.hp<=0)f={row:2,col:3};else if(e.attack?.pattern==='ancientCheckerSlam')f={row:2,col:e.elapsed<.45?0:e.elapsed<1.1?1:e.elapsed<1.4?2:e.elapsed<1.75?0:e.elapsed<2.4?1:e.elapsed<2.7?2:3};let q=project(e.x,e.y),sw=ancientColossusSheet.naturalWidth/4,sh=ancientColossusSheet.naturalHeight/3,w=310,h=w*sh/sw,anchor=[[.89,.89,.89,.89],[.85,.88,.88,.84],[.82,.85,.83,.80]][f.row][f.col];ctx.save();ctx.translate(q.x,q.y);ctx.scale(e.facing||1,1);ctx.filter=e.flash>0?'brightness(1.8)':'none';if(typeof drawPreparedEnemySprite==='function')drawPreparedEnemySprite(ctx,ancientColossusSheet,f.col*sw,f.row*sh,sw,sh,-w/2,-h*anchor,w,h);else ctx.drawImage(ancientColossusSheet,f.col*sw,f.row*sh,sw,sh,-w/2,-h*anchor,w,h);ctx.restore();return true;};
const ancientColossusSizeBase=enemyVisualSize;enemyVisualSize=e=>e.species==='r9e4'?240:ancientColossusSizeBase(e);
const ancientColossusGroundBase=drawGroundEffects;drawGroundEffects=()=>{ancientColossusGroundBase();for(let e of (typeof enemyRenderList==='function'?enemyRenderList('r9e4'):enemies)){let a=e.attack;if(e.species!=='r9e4'||e.hp<=0||a?.pattern!=='ancientCheckerSlam'||!visibleAt(a.center.x,a.center.y)||e.elapsed>=2.7)continue;let q=project(a.center.x,a.center.y),phase=e.elapsed<1.35?0:1,impact=e.elapsed>=2.4||(e.elapsed>=1.1&&e.elapsed<1.35);ctx.save();ctx.translate(q.x,q.y);ctx.transform(ISOX,ISOY,-ISOX,ISOY,0,0);ctx.lineWidth=2;for(let y=0;y<3;y++)for(let x=0;x<3;x++){let active=(x+y)%2===phase;ctx.fillStyle=active?(impact?'#e7c78488':'#e7b35c44'):'#6ce7d00b';ctx.strokeStyle=active?'#ffd692':'#6ce7d066';ctx.beginPath();ctx.rect(x*90-135,y*90-135,90,90);ctx.fill();ctx.stroke();if(active){ctx.beginPath();ctx.moveTo(x*90-105,y*90-105);ctx.lineTo(x*90-75,y*90-75);ctx.moveTo(x*90-75,y*90-105);ctx.lineTo(x*90-105,y*90-75);ctx.stroke();}}ctx.restore();}};

if(typeof registerDirectEnemy==='function')registerDirectEnemy('r9e4',animateEnemy,drawRegionEnemy);
